files.schema/types.schema.json:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "types.schema.json",
  "$comment": "SpecBoard がプロジェクト「Harbor City Library Network」から作ったファイルです。書き換えはプロジェクトで",
  "$defs": {
    "CurrencyCode": {
      "title": "CurrencyCode",
      "description": "通貨 — 金額の単位。館の会計は円で締めるが、海外の出版社への発注と寄贈の評価額は外貨で受ける。換算は会計の側で行い、ここでは持たない。",
      "type": "string",
      "enum": [
        "JPY",
        "USD",
        "EUR"
      ]
    },
    "RoundingMode": {
      "title": "RoundingMode",
      "description": "端数の扱い — 延滞金と按分した送料に 1 円未満が出たときの扱い。",
      "type": "string",
      "enum": [
        "floor",
        "round",
        "ceil"
      ]
    },
    "MaterialType": {
      "title": "MaterialType",
      "description": "資料の種類 — 貸出の規則と棚の割り当てを分ける単位。電子書籍は棚を持たないが、貸出の規則は同じ表で引く。",
      "type": "string",
      "enum": [
        "book",
        "magazine",
        "audio",
        "video",
        "map",
        "kit",
        "ebook",
        "score",
        "newspaper",
        "game"
      ]
    },
    "MemberCategory": {
      "title": "MemberCategory",
      "description": "利用者の区分 — 貸出の上限と延滞金の率を変える区分。年齢で自動では変えず、更新の窓口で確かめて変える。",
      "type": "string",
      "enum": [
        "adult",
        "child",
        "student",
        "senior",
        "corporate"
      ]
    },
    "MemberStatus": {
      "title": "MemberStatus",
      "description": "利用者の状態",
      "type": "string",
      "enum": [
        "active",
        "suspended",
        "expired"
      ]
    },
    "LoanStatus": {
      "title": "LoanStatus",
      "description": "貸出の状態 — 返却の記録が付いた時点で returned。紛失の届けが出たものは lost にして延滞金を止める。",
      "type": "string",
      "enum": [
        "open",
        "returned",
        "overdue",
        "lost"
      ]
    },
    "ReservationStatus": {
      "title": "ReservationStatus",
      "description": "予約の状態",
      "type": "string",
      "enum": [
        "waiting",
        "ready",
        "collected",
        "cancelled",
        "expired"
      ]
    },
    "TransferStatus": {
      "title": "TransferStatus",
      "description": "配送の状態 — 館間配送の荷の状態。荷を開けて数が合わないときは rejected にして送り元へ戻す。",
      "type": "string",
      "enum": [
        "requested",
        "packed",
        "in_transit",
        "received",
        "rejected"
      ]
    },
    "CopyCondition": {
      "title": "CopyCondition",
      "description": "資料の傷み",
      "type": "string",
      "enum": [
        "new",
        "good",
        "worn",
        "damaged"
      ]
    },
    "ShelfZone": {
      "title": "ShelfZone",
      "description": "棚の区域 — 開架・参考・児童・閉架。閉架の資料は予約を通してだけ出す。",
      "type": "string",
      "enum": [
        "general",
        "reference",
        "children",
        "closed_stack"
      ]
    },
    "Weekday": {
      "title": "Weekday",
      "description": "曜日",
      "type": "string",
      "enum": [
        "mon",
        "tue",
        "wed",
        "thu",
        "fri",
        "sat",
        "sun"
      ]
    },
    "NotificationChannel": {
      "title": "NotificationChannel",
      "description": "知らせる手段 — 利用者が選んだ手段で知らせる。郵便は費用がかかるので、延滞の三度目の知らせだけに使う。",
      "type": "string",
      "enum": [
        "email",
        "sms",
        "post",
        "app"
      ]
    },
    "FineReason": {
      "title": "FineReason",
      "description": "延滞金の理由",
      "type": "string",
      "enum": [
        "overdue",
        "damage",
        "loss"
      ]
    },
    "PaymentMethod": {
      "title": "PaymentMethod",
      "description": "払い方",
      "type": "string",
      "enum": [
        "cash",
        "card",
        "transfer",
        "waiver"
      ]
    },
    "AcquisitionMethod": {
      "title": "AcquisitionMethod",
      "description": "受け入れの方法",
      "type": "string",
      "enum": [
        "purchase",
        "donation",
        "exchange"
      ]
    },
    "OrderStatus": {
      "title": "OrderStatus",
      "description": "発注の状態 — 一部だけ届いた発注は partially_received のまま、残りが届くか取り消すまで閉じない。",
      "type": "string",
      "enum": [
        "draft",
        "ordered",
        "partially_received",
        "received",
        "cancelled"
      ]
    },
    "VendorKind": {
      "title": "VendorKind",
      "description": "取引先の種類",
      "type": "string",
      "enum": [
        "publisher",
        "distributor",
        "bookstore"
      ]
    },
    "EventKind": {
      "title": "EventKind",
      "description": "行事の種類",
      "type": "string",
      "enum": [
        "reading",
        "workshop",
        "exhibition",
        "lecture"
      ]
    },
    "AudienceAge": {
      "title": "AudienceAge",
      "description": "対象の年齢",
      "type": "string",
      "enum": [
        "children",
        "teens",
        "adults",
        "all"
      ]
    },
    "RoomKind": {
      "title": "RoomKind",
      "description": "部屋の種類",
      "type": "string",
      "enum": [
        "study",
        "meeting",
        "hall"
      ]
    },
    "BookingStatus": {
      "title": "BookingStatus",
      "description": "予約の確定",
      "type": "string",
      "enum": [
        "held",
        "confirmed",
        "cancelled"
      ]
    },
    "StaffRole": {
      "title": "StaffRole",
      "description": "職員の役割 — 記録に名前を残す職員の役割。ボランティアは承認の欄に名前を書けない。",
      "type": "string",
      "enum": [
        "librarian",
        "clerk",
        "manager",
        "volunteer"
      ]
    },
    "ShiftKind": {
      "title": "ShiftKind",
      "description": "勤務の区分",
      "type": "string",
      "enum": [
        "morning",
        "afternoon",
        "evening"
      ]
    },
    "AuditAction": {
      "title": "AuditAction",
      "description": "監査の操作",
      "type": "string",
      "enum": [
        "create",
        "update",
        "delete",
        "approve",
        "reject"
      ]
    },
    "RecordKind": {
      "title": "RecordKind",
      "description": "記録の種類 — 監査と索引が指す記録の種類。record_type の値から接頭辞を外したもの。",
      "type": "string",
      "enum": [
        "loan-record",
        "reservation",
        "transfer-manifest",
        "purchase-order",
        "fine-assessment"
      ]
    },
    "LanguageCode": {
      "title": "LanguageCode",
      "description": "言語",
      "type": "string",
      "enum": [
        "ja",
        "en",
        "zh",
        "ko",
        "es"
      ]
    },
    "ClassificationScheme": {
      "title": "ClassificationScheme",
      "description": "分類法",
      "type": "string",
      "enum": [
        "ndc",
        "ddc",
        "local"
      ]
    },
    "ItemFormat": {
      "title": "ItemFormat",
      "description": "形態",
      "type": "string",
      "enum": [
        "print",
        "large_print",
        "braille",
        "digital"
      ]
    },
    "DeliveryMode": {
      "title": "DeliveryMode",
      "description": "配送の手段",
      "type": "string",
      "enum": [
        "van",
        "courier",
        "post"
      ]
    },
    "VanRoute": {
      "title": "VanRoute",
      "description": "巡回車の経路 — 巡回車は週に二回、四つの経路で分館を回る。経路の外の館へは宅配で送る。",
      "type": "string",
      "enum": [
        "north",
        "south",
        "east",
        "west"
      ]
    },
    "HoldPickup": {
      "title": "HoldPickup",
      "description": "受け取りの場所",
      "type": "string",
      "enum": [
        "branch",
        "locker",
        "home_delivery"
      ]
    },
    "RenewalRule": {
      "title": "RenewalRule",
      "description": "延長の可否",
      "type": "string",
      "enum": [
        "allowed",
        "once",
        "never"
      ]
    },
    "SeriesStatus": {
      "title": "SeriesStatus",
      "description": "シリーズの状態",
      "type": "string",
      "enum": [
        "ongoing",
        "completed",
        "discontinued"
      ]
    },
    "DigitalLicense": {
      "title": "DigitalLicense",
      "description": "電子資料の契約",
      "type": "string",
      "enum": [
        "one_user",
        "multi_user",
        "unlimited"
      ]
    },
    "AccessLevel": {
      "title": "AccessLevel",
      "description": "公開の範囲",
      "type": "string",
      "enum": [
        "public",
        "staff",
        "restricted"
      ]
    },
    "ApprovalDecision": {
      "title": "ApprovalDecision",
      "description": "承認の結果",
      "type": "string",
      "enum": [
        "approved",
        "rejected",
        "deferred"
      ]
    },
    "SurveyScale": {
      "title": "SurveyScale",
      "description": "満足度 — 利用者アンケートの五段階。3 を「ふつう」とする。",
      "type": "string",
      "enum": [
        "1",
        "2",
        "3",
        "4",
        "5"
      ]
    },
    "WeedingReason": {
      "title": "WeedingReason",
      "description": "除籍の理由",
      "type": "string",
      "enum": [
        "outdated",
        "damaged",
        "duplicate",
        "low_use"
      ]
    },
    "BudgetPeriod": {
      "title": "BudgetPeriod",
      "description": "予算の期間",
      "type": "string",
      "enum": [
        "monthly",
        "quarterly",
        "yearly"
      ]
    },
    "ContactPurpose": {
      "title": "ContactPurpose",
      "description": "連絡先の用途",
      "type": "string",
      "enum": [
        "billing",
        "notices",
        "emergency"
      ]
    },
    "DocumentKind": {
      "title": "DocumentKind",
      "description": "本人確認の書類",
      "type": "string",
      "enum": [
        "id_card",
        "passport",
        "student_card",
        "health_card"
      ]
    },
    "CatalogKind": {
      "title": "CatalogKind",
      "description": "索引の種類 — 索引の一行が何の索引かを言う。種類ごとに指す相手が違う。",
      "type": "string",
      "enum": [
        "subject",
        "author",
        "series"
      ]
    },
    "TemperatureZone": {
      "title": "TemperatureZone",
      "description": "保管の温度帯",
      "type": "string",
      "enum": [
        "normal",
        "cool",
        "archive"
      ]
    },
    "ImportFormat": {
      "title": "ImportFormat",
      "description": "取り込みの形式",
      "type": "string",
      "enum": [
        "marc21",
        "csv",
        "json"
      ]
    },
    "PriorityLevel": {
      "title": "PriorityLevel",
      "description": "優先度",
      "type": "string",
      "enum": [
        "low",
        "normal",
        "high",
        "urgent"
      ]
    },
    "MoneyAmount": {
      "title": "MoneyAmount",
      "description": "金額 — 金額は通貨と最小単位の整数で持つ。浮動小数で持つと延滞金の合計が館ごとにずれるので、ここへ切り出して全部の金額欄が同じ形を使う。",
      "type": "object",
      "properties": {
        "currency": {
          "$ref": "#/$defs/CurrencyCode"
        },
        "minor_units": {
          "type": "integer",
          "description": "通貨の最小単位での整数。円なら 1 円単位"
        },
        "rounding": {
          "$ref": "#/$defs/RoundingMode"
        }
      },
      "required": [
        "currency",
        "minor_units"
      ],
      "additionalProperties": false
    },
    "PostalAddress": {
      "title": "PostalAddress",
      "description": "住所 — 郵送と配送に使う住所。行は利用者が書いたとおりに持ち、正規化は送り状を作るときにだけ行う。",
      "type": "object",
      "properties": {
        "postal_code": {
          "type": "string",
          "description": "ハイフンを含めない 7 桁",
          "x-rules": [
            {
              "kind": "pattern",
              "regex": "^[0-9]{7}$"
            }
          ]
        },
        "region": {
          "type": "string"
        },
        "city": {
          "type": "string"
        },
        "lines": {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        "address_id": {
          "type": "string",
          "format": "uuid"
        }
      },
      "required": [
        "postal_code",
        "region",
        "city",
        "lines"
      ],
      "additionalProperties": false
    },
    "ContactPoint": {
      "title": "ContactPoint",
      "description": "連絡先",
      "type": "object",
      "properties": {
        "contact_id": {
          "type": "string",
          "format": "uuid"
        },
        "purpose": {
          "$ref": "#/$defs/ContactPurpose"
        },
        "channel": {
          "$ref": "#/$defs/NotificationChannel"
        },
        "address": {
          "type": "string",
          "description": "メールアドレス・電話番号・住所のいずれか。channel が決める"
        }
      },
      "required": [
        "contact_id",
        "purpose",
        "channel",
        "address"
      ],
      "additionalProperties": false
    },
    "PersonName": {
      "title": "PersonName",
      "description": "人の名前 — 姓と名を分けて持つ。読みは窓口で確かめたものだけを入れる。",
      "type": "object",
      "properties": {
        "family": {
          "type": "string"
        },
        "given": {
          "type": "string"
        },
        "family_kana": {
          "type": "string"
        },
        "given_kana": {
          "type": "string"
        }
      },
      "required": [
        "family",
        "given"
      ],
      "additionalProperties": false
    },
    "DateRange": {
      "title": "DateRange",
      "description": "期間 — 両端を含む期間。終わりの無い期間は until を null にする。",
      "type": "object",
      "properties": {
        "since": {
          "type": "string",
          "format": "date-time"
        },
        "until": {
          "type": [
            "string",
            "null"
          ],
          "format": "date-time"
        }
      },
      "required": [
        "since",
        "until"
      ],
      "additionalProperties": false
    },
    "TimeWindow": {
      "title": "TimeWindow",
      "description": "時間帯",
      "type": "object",
      "properties": {
        "opens": {
          "type": "string",
          "description": "HH:MM"
        },
        "closes": {
          "type": "string",
          "description": "HH:MM"
        }
      },
      "required": [
        "opens",
        "closes"
      ],
      "additionalProperties": false
    },
    "StaffRef": {
      "title": "StaffRef",
      "description": "職員 — 記録に残す職員。名前は控えず、職員の id と役割だけを持つ。",
      "type": "object",
      "properties": {
        "staff_id": {
          "type": "string",
          "format": "uuid"
        },
        "role": {
          "$ref": "#/$defs/StaffRole"
        }
      },
      "required": [
        "staff_id",
        "role"
      ],
      "additionalProperties": false
    },
    "BranchRef": {
      "title": "BranchRef",
      "description": "館",
      "type": "object",
      "properties": {
        "branch_id": {
          "type": "string",
          "format": "uuid"
        },
        "code": {
          "type": "string",
          "description": "館の 3 文字の略号"
        }
      },
      "required": [
        "branch_id",
        "code"
      ],
      "additionalProperties": false
    },
    "RecordRef": {
      "title": "RecordRef",
      "description": "記録への参照 — どの種類の記録かと、その記録の番号の組。番号だけでは種類をまたいで重なるので、必ず二つで指す。",
      "type": "object",
      "properties": {
        "record_type": {
          "type": "string",
          "description": "指す記録の record_type"
        },
        "record_key": {
          "type": "string",
          "description": "指す記録の番号"
        }
      },
      "required": [
        "record_type",
        "record_key"
      ],
      "additionalProperties": false
    },
    "ApprovalStamp": {
      "title": "ApprovalStamp",
      "description": "承認の印 — 承認した職員と結果と時刻。承認の欄を持つ記録はどれもこの形を使う。",
      "type": "object",
      "properties": {
        "decision": {
          "$ref": "#/$defs/ApprovalDecision"
        },
        "approver": {
          "$ref": "#/$defs/StaffRef"
        },
        "decided_at": {
          "type": "string",
          "format": "date-time"
        },
        "comment": {
          "type": "string"
        }
      },
      "required": [
        "decision",
        "approver",
        "decided_at"
      ],
      "additionalProperties": false
    },
    "Identifier": {
      "title": "Identifier",
      "description": "識別子",
      "type": "object",
      "properties": {
        "scheme": {
          "type": "string",
          "description": "isbn・issn・館の登録番号など"
        },
        "identifier_value": {
          "type": "string"
        }
      },
      "required": [
        "scheme",
        "identifier_value"
      ],
      "additionalProperties": false
    },
    "ShelfLocation": {
      "title": "ShelfLocation",
      "description": "棚の位置",
      "type": "object",
      "properties": {
        "location_id": {
          "type": "string",
          "format": "uuid"
        },
        "zone": {
          "$ref": "#/$defs/ShelfZone"
        },
        "shelf": {
          "type": "string"
        },
        "position": {
          "type": "integer"
        }
      },
      "required": [
        "location_id",
        "zone",
        "shelf",
        "position"
      ],
      "additionalProperties": false
    },
    "CallNumber": {
      "title": "CallNumber",
      "description": "請求記号 — 分類記号と著者記号の組。分類法が館の独自分類のときは cutter を持たない。",
      "type": "object",
      "properties": {
        "scheme": {
          "$ref": "#/$defs/ClassificationScheme"
        },
        "class_number": {
          "type": "string"
        },
        "cutter": {
          "type": "string"
        }
      },
      "required": [
        "scheme",
        "class_number"
      ],
      "additionalProperties": false
    },
    "Contributor": {
      "title": "Contributor",
      "description": "著者など",
      "type": "object",
      "properties": {
        "contributor_id": {
          "type": "string",
          "format": "uuid"
        },
        "name": {
          "$ref": "#/$defs/PersonName"
        },
        "role": {
          "type": "string",
          "description": "著・編・訳・絵など"
        }
      },
      "required": [
        "contributor_id",
        "name",
        "role"
      ],
      "additionalProperties": false
    },
    "SeriesInfo": {
      "title": "SeriesInfo",
      "description": "シリーズ",
      "type": "object",
      "properties": {
        "series_id": {
          "type": "string",
          "format": "uuid"
        },
        "title": {
          "type": "string"
        },
        "number": {
          "type": "string"
        },
        "status": {
          "$ref": "#/$defs/SeriesStatus"
        }
      },
      "required": [
        "series_id",
        "title",
        "status"
      ],
      "additionalProperties": false
    },
    "PhysicalDescription": {
      "title": "PhysicalDescription",
      "description": "形態の記述",
      "type": "object",
      "properties": {
        "format": {
          "$ref": "#/$defs/ItemFormat"
        },
        "pages": {
          "type": "integer"
        },
        "height_cm": {
          "type": "integer"
        }
      },
      "required": [
        "format"
      ],
      "additionalProperties": false
    },
    "SubjectHeading": {
      "title": "SubjectHeading",
      "description": "件名",
      "type": "object",
      "properties": {
        "heading_id": {
          "type": "string",
          "format": "uuid"
        },
        "heading": {
          "type": "string"
        },
        "scheme": {
          "type": "string"
        }
      },
      "required": [
        "heading_id",
        "heading",
        "scheme"
      ],
      "additionalProperties": false
    },
    "ItemCondition": {
      "title": "ItemCondition",
      "description": "資料の状態 — 点検と返却のたびに付ける状態。前の状態は消さずに、記録の側に並べて残す。",
      "type": "object",
      "properties": {
        "condition": {
          "$ref": "#/$defs/CopyCondition"
        },
