        "record_type",
        "schema_version",
        "index_id",
        "entries",
        "stats",
        "built_at",
        "record_meta"
      ],
      "additionalProperties": false
    }
  }
}

files.ts/types.ts:
// SpecBoard がプロジェクト「Harbor City Library Network」から作ったファイルです。書き換えはプロジェクトで
/** 通貨 — 金額の単位。館の会計は円で締めるが、海外の出版社への発注と寄贈の評価額は外貨で受ける。換算は会計の側で行い、ここでは持たない。 */
export type CurrencyCode = "JPY" | "USD" | "EUR";

/** 端数の扱い — 延滞金と按分した送料に 1 円未満が出たときの扱い。 */
export type RoundingMode = "floor" | "round" | "ceil";

/** 資料の種類 — 貸出の規則と棚の割り当てを分ける単位。電子書籍は棚を持たないが、貸出の規則は同じ表で引く。 */
export type MaterialType = "book" | "magazine" | "audio" | "video" | "map" | "kit" | "ebook" | "score" | "newspaper" | "game";

/** 利用者の区分 — 貸出の上限と延滞金の率を変える区分。年齢で自動では変えず、更新の窓口で確かめて変える。 */
export type MemberCategory = "adult" | "child" | "student" | "senior" | "corporate";

/** 利用者の状態 */
export type MemberStatus = "active" | "suspended" | "expired";

/** 貸出の状態 — 返却の記録が付いた時点で returned。紛失の届けが出たものは lost にして延滞金を止める。 */
export type LoanStatus = "open" | "returned" | "overdue" | "lost";

/** 予約の状態 */
export type ReservationStatus = "waiting" | "ready" | "collected" | "cancelled" | "expired";

/** 配送の状態 — 館間配送の荷の状態。荷を開けて数が合わないときは rejected にして送り元へ戻す。 */
export type TransferStatus = "requested" | "packed" | "in_transit" | "received" | "rejected";

/** 資料の傷み */
export type CopyCondition = "new" | "good" | "worn" | "damaged";

/** 棚の区域 — 開架・参考・児童・閉架。閉架の資料は予約を通してだけ出す。 */
export type ShelfZone = "general" | "reference" | "children" | "closed_stack";

/** 曜日 */
export type Weekday = "mon" | "tue" | "wed" | "thu" | "fri" | "sat" | "sun";

/** 知らせる手段 — 利用者が選んだ手段で知らせる。郵便は費用がかかるので、延滞の三度目の知らせだけに使う。 */
export type NotificationChannel = "email" | "sms" | "post" | "app";

/** 延滞金の理由 */
export type FineReason = "overdue" | "damage" | "loss";

/** 払い方 */
export type PaymentMethod = "cash" | "card" | "transfer" | "waiver";

/** 受け入れの方法 */
export type AcquisitionMethod = "purchase" | "donation" | "exchange";

/** 発注の状態 — 一部だけ届いた発注は partially_received のまま、残りが届くか取り消すまで閉じない。 */
export type OrderStatus = "draft" | "ordered" | "partially_received" | "received" | "cancelled";

/** 取引先の種類 */
export type VendorKind = "publisher" | "distributor" | "bookstore";

/** 行事の種類 */
export type EventKind = "reading" | "workshop" | "exhibition" | "lecture";

/** 対象の年齢 */
export type AudienceAge = "children" | "teens" | "adults" | "all";

/** 部屋の種類 */
export type RoomKind = "study" | "meeting" | "hall";

/** 予約の確定 */
export type BookingStatus = "held" | "confirmed" | "cancelled";

/** 職員の役割 — 記録に名前を残す職員の役割。ボランティアは承認の欄に名前を書けない。 */
export type StaffRole = "librarian" | "clerk" | "manager" | "volunteer";

/** 勤務の区分 */
export type ShiftKind = "morning" | "afternoon" | "evening";

/** 監査の操作 */
export type AuditAction = "create" | "update" | "delete" | "approve" | "reject";

/** 記録の種類 — 監査と索引が指す記録の種類。record_type の値から接頭辞を外したもの。 */
export type RecordKind = "loan-record" | "reservation" | "transfer-manifest" | "purchase-order" | "fine-assessment";

/** 言語 */
export type LanguageCode = "ja" | "en" | "zh" | "ko" | "es";

/** 分類法 */
export type ClassificationScheme = "ndc" | "ddc" | "local";

/** 形態 */
export type ItemFormat = "print" | "large_print" | "braille" | "digital";

/** 配送の手段 */
export type DeliveryMode = "van" | "courier" | "post";

/** 巡回車の経路 — 巡回車は週に二回、四つの経路で分館を回る。経路の外の館へは宅配で送る。 */
export type VanRoute = "north" | "south" | "east" | "west";

/** 受け取りの場所 */
export type HoldPickup = "branch" | "locker" | "home_delivery";

/** 延長の可否 */
export type RenewalRule = "allowed" | "once" | "never";

/** シリーズの状態 */
export type SeriesStatus = "ongoing" | "completed" | "discontinued";

/** 電子資料の契約 */
export type DigitalLicense = "one_user" | "multi_user" | "unlimited";

/** 公開の範囲 */
export type AccessLevel = "public" | "staff" | "restricted";

/** 承認の結果 */
export type ApprovalDecision = "approved" | "rejected" | "deferred";

/** 満足度 — 利用者アンケートの五段階。3 を「ふつう」とする。 */
export type SurveyScale = "1" | "2" | "3" | "4" | "5";

/** 除籍の理由 */
export type WeedingReason = "outdated" | "damaged" | "duplicate" | "low_use";

/** 予算の期間 */
export type BudgetPeriod = "monthly" | "quarterly" | "yearly";

/** 連絡先の用途 */
export type ContactPurpose = "billing" | "notices" | "emergency";

/** 本人確認の書類 */
export type DocumentKind = "id_card" | "passport" | "student_card" | "health_card";

/** 索引の種類 — 索引の一行が何の索引かを言う。種類ごとに指す相手が違う。 */
export type CatalogKind = "subject" | "author" | "series";

/** 保管の温度帯 */
export type TemperatureZone = "normal" | "cool" | "archive";

/** 取り込みの形式 */
export type ImportFormat = "marc21" | "csv" | "json";

/** 優先度 */
export type PriorityLevel = "low" | "normal" | "high" | "urgent";

/** 金額 — 金額は通貨と最小単位の整数で持つ。浮動小数で持つと延滞金の合計が館ごとにずれるので、ここへ切り出して全部の金額欄が同じ形を使う。 */
export interface MoneyAmount {
  currency: CurrencyCode;
  /** 通貨の最小単位での整数。円なら 1 円単位 */
  minor_units: number;
  rounding?: RoundingMode;
}

/** 住所 — 郵送と配送に使う住所。行は利用者が書いたとおりに持ち、正規化は送り状を作るときにだけ行う。 */
export interface PostalAddress {
  /** ハイフンを含めない 7 桁 — pattern(regex=^[0-9]{7}$) — 正規表現に一致すること */
  postal_code: string;
  region: string;
  city: string;
  lines: string[];
  address_id?: string;
}

/** 連絡先 */
export interface ContactPoint {
  contact_id: string;
  purpose: ContactPurpose;
  channel: NotificationChannel;
  /** メールアドレス・電話番号・住所のいずれか。channel が決める */
  address: string;
}

/** 人の名前 — 姓と名を分けて持つ。読みは窓口で確かめたものだけを入れる。 */
export interface PersonName {
  family: string;
  given: string;
  family_kana?: string;
  given_kana?: string;
}

/** 期間 — 両端を含む期間。終わりの無い期間は until を null にする。 */
export interface DateRange {
  since: string;
  until: string | null;
}

/** 時間帯 */
export interface TimeWindow {
  /** HH:MM */
  opens: string;
  /** HH:MM */
  closes: string;
}

/** 職員 — 記録に残す職員。名前は控えず、職員の id と役割だけを持つ。 */
export interface StaffRef {
  staff_id: string;
  role: StaffRole;
}

/** 館 */
export interface BranchRef {
  branch_id: string;
  /** 館の 3 文字の略号 */
  code: string;
}

/** 記録への参照 — どの種類の記録かと、その記録の番号の組。番号だけでは種類をまたいで重なるので、必ず二つで指す。 */
export interface RecordRef {
  /** 指す記録の record_type */
  record_type: string;
  /** 指す記録の番号 */
  record_key: string;
}

/** 承認の印 — 承認した職員と結果と時刻。承認の欄を持つ記録はどれもこの形を使う。 */
export interface ApprovalStamp {
  decision: ApprovalDecision;
  approver: StaffRef;
  decided_at: string;
  comment?: string;
}

/** 識別子 */
export interface Identifier {
  /** isbn・issn・館の登録番号など */
  scheme: string;
  identifier_value: string;
}

/** 棚の位置 */
export interface ShelfLocation {
  location_id: string;
  zone: ShelfZone;
  shelf: string;
  position: number;
}

/** 請求記号 — 分類記号と著者記号の組。分類法が館の独自分類のときは cutter を持たない。 */
export interface CallNumber {
  scheme: ClassificationScheme;
  class_number: string;
  cutter?: string;
}

/** 著者など */
export interface Contributor {
  contributor_id: string;
  name: PersonName;
  /** 著・編・訳・絵など */
  role: string;
}

/** シリーズ */
export interface SeriesInfo {
  series_id: string;
  title: string;
  number?: string;
  status: SeriesStatus;
}

/** 形態の記述 */
export interface PhysicalDescription {
  format: ItemFormat;
  pages?: number;
  height_cm?: number;
}

/** 件名 */
export interface SubjectHeading {
  heading_id: string;
  heading: string;
  scheme: string;
}

/** 資料の状態 — 点検と返却のたびに付ける状態。前の状態は消さずに、記録の側に並べて残す。 */
export interface ItemCondition {
  condition: CopyCondition;
  noted_at: string;
  noted_by: StaffRef;
}

/** 貸出の一点 */
export interface LoanLine {
  item_id: string;
  due_on: string;
  fee?: MoneyAmount;
}

/** 返却の一点 */
export interface ReturnLine {
  item_id: string;
  returned_at: string;
  condition: ItemCondition;
  late_fee: MoneyAmount | null;
}

/** 荷の一点 */
export interface PackedItem {
  item_id: string;
  from_branch: BranchRef;
  to_branch: BranchRef;
  declared_value: MoneyAmount;
}

/** 荷の封 — 封の番号と封をした職員。受け取った館は封の番号を確かめてから開ける。 */
export interface PackageSeal {
  seal_id: string;
  sealed_by: StaffRef;
  sealed_at: string;
}

/** 発注の一行 — derivedFrom(field=total, from=unit_price, note=単価と数から計算し直して、合わない行を受け付けない) — from から再計算した値と一致すること */
export interface OrderLine {
  line_id: string;
  title: string;
  isbn?: string;
  quantity: number;
  unit_price: MoneyAmount;
  total: MoneyAmount;
}

/** 請求の一行 */
export interface InvoiceLine {
  order_line_id: string;
  amount: MoneyAmount;
  tax: TaxLine;
}

/** 税 */
export interface TaxLine {
  tax_id: string;
  rate_percent: number;
  amount: MoneyAmount;
}

/** 支払いの一行 */
export interface PaymentLine {
  payment_id: string;
  method: PaymentMethod;
  amount: MoneyAmount;
}

/** 値引き */
export interface Discount {
  discount_id: string;
  reason: string;
  amount: MoneyAmount;
}

/** 料金の一項目 */
export interface FeeItem {
  fee_id: string;
  label: string;
  amount: MoneyAmount;
}

/** 行事の回 */
export interface EventSession {
  session_id: string;
  window: TimeWindow;
  room_id: string;
  capacity: number;
  entry_fee: MoneyAmount | null;
}

/** 講師 */
export interface Speaker {
  speaker_id: string;
  name: PersonName;
  honorarium: MoneyAmount;
  travel_cost?: MoneyAmount;
}

/** 参加の数 */
export interface Attendance {
  expected: number;
  actual: number | null;
}

/** 部屋の設備 */
export interface RoomEquipment {
  equipment_id: string;
  label: string;
  rental_fee: MoneyAmount;
}

/** 勤務の枠 */
export interface ShiftSlot {
  slot_id: string;
  kind: ShiftKind;
  window: TimeWindow;
  staff: StaffRef;
}

/** 点検の一行 */
export interface CountLine {
  line_id: string;
  location: ShelfLocation;
  expected: number;
  found: number;
}

/** 点検の食い違い — 点検で見つからなかった資料と、あるはずのない資料。どちらも館の id と資料の id で持つ。 */
export interface Discrepancy {
  item_id: string;
  branch: BranchRef;
  missing: boolean;
  replacement_cost: MoneyAmount;
}

/** 契約の条件 */
export interface LicenseTerms {
  license: DigitalLicense;
  seats: number | null;
  price: MoneyAmount;
  period: DateRange;
}

/** アンケートの回答 */
export interface SurveyAnswer {
  question_id: string;
  score: SurveyScale;
  comment?: string;
}

/** 操作した人 */
export interface AuditActor {
  staff: StaffRef;
  /** 窓口の端末の番号 */
  terminal_id: string;
}

/** 操作の対象 */
export interface AuditTarget {
  target_id: string;
  record: RecordRef;
  branch: BranchRef;
}

/** 予算の一行 — 費目ごとの予算。使った額は受け入れのたびに足し、予算を超える発注は承認を要る。 */
export interface BudgetLine {
  line_id: string;
  period: BudgetPeriod;
  allocated: MoneyAmount;
  spent: MoneyAmount;
  reserve?: MoneyAmount;
}

/** 開館時間 */
export interface OpeningHours {
  weekday: Weekday;
  /** 休館日は null */
  hours: TimeWindow | null;
}

/** 休館日 */
export interface Holiday {
  holiday_id: string;
  date: string;
  reason: string;
}

/** お知らせの文面 — 知らせる手段と言語ごとの文面。返す日や館の名前は、送るときに文面へ差し込む。 */
export interface NoticeTemplate {
  template_id: string;
  channel: NotificationChannel;
  purpose: ContactPurpose;
  language: LanguageCode;
  body: string;
}

/** 保存の規則 */
export interface RetentionRule {
  rule_id: string;
  record_kind: RecordKind;
  keep_days: number;
  zone?: TemperatureZone;
}

/** 貸出の規則 — 資料の種類と利用者の区分の組ごとの規則。組は一つにつき一行で、重なる行は受け付けない。 */
export interface LoanRule {
  rule_id: string;
  material: MaterialType;
  member: MemberCategory;
  loan_days: number;
  max_items: number;
  renewal: RenewalRule;
  daily_fine: MoneyAmount;
  fine_cap: MoneyAmount;
}

/** 予約の規則 */
export interface ReservationRule {
  rule_id: string;
  member: MemberCategory;
  max_reservations: number;
  hold_days: number;
  pickup: HoldPickup;
  no_show_fee: MoneyAmount;
}

/** 延滞金の規則 */
export interface FineRule {
  rule_id: string;
  reason: FineReason;
  amount: MoneyAmount;
  cap: MoneyAmount;
  grace_days: number;
}

/** 配送の経路 — 巡回車の経路と回る館の順。順番は荷を積む順でもあるので、並べ替えると積み荷目録が合わなくなる。 */
export interface TransferRoute {
  route_id: string;
  route: VanRoute;
  mode: DeliveryMode;
  /** uniqueBy(field=branch_id) — 配列内で重複しないこと。field 省略時は要素そのもの */
  stops: BranchRef[];
  cost_per_trip: MoneyAmount;
}

/** 取引の条件 */
export interface VendorTerms {
  vendor_id: string;
  kind: VendorKind;
  discount_percent: number;
  shipping_fee: MoneyAmount;
  free_shipping_over?: MoneyAmount;
}

/** 会費 */
export interface MembershipFee {
  member: MemberCategory;
  annual_fee: MoneyAmount;
  card_reissue_fee: MoneyAmount;
}

/** 館の扱える範囲 — 館ごとに使ってよい貸出の規則。規則の本体は全体の設定にあり、ここでは id で選ぶだけ。 */
export interface BranchScope {
  branch_id: string;
  /** 使ってよい貸出の規則の id。全体の設定の規則の一覧にあるものだけ — LoanRule に存在する値 — memberOf(target=NetworkConfiguration.lending_policy.loan_rules[].rule_id) — 値が target の集合に含まれること。pointsAt の in が「どこで定義されているか」なのに対し、これは「そのうちどこまで使ってよいか」という絞り込みを表す */
  allowed_rule_ids: string[];
  supervisors: StaffRef[];
}

/** 貸出の方針 — 貸出の規則の一覧と、館ごとの扱える範囲。規則の id は全体で一意で、館の範囲は id で規則を選ぶ。 */
export interface LendingPolicy {
  policy_id: string;
  /** sortedBy(field=rule_id) — 配列がこの順で並んでいること。field 省略時は要素そのもので比較 — uniqueBy(field=rule_id) — 配列内で重複しないこと。field 省略時は要素そのもの */
  loan_rules: LoanRule[];
  branch_scopes: BranchScope[];
  default_loan_days: number;
  max_renewals: number;
}

/** 予約の方針 */
export interface ReservationPolicy {
  policy_id: string;
  rules: ReservationRule[];
  queue_limit: number;
  notice: NoticeTemplate;
}

/** 延滞金の方針 — 延滞金の規則と上限。上限は一点ごとではなく一回の貸出ごとにかける。 */
export interface FinePolicy {
  policy_id: string;
  rules: FineRule[];
  monthly_cap: MoneyAmount;
  waiver_limit: MoneyAmount;
}

/** 配送の方針 */
export interface TransferPolicy {
  policy_id: string;
  routes: TransferRoute[];
  max_items_per_package: number;
  insurance_threshold: MoneyAmount;
}

/** 受け入れの方針 */
export interface AcquisitionPolicy {
  policy_id: string;
  vendors: VendorTerms[];
  approval_threshold: MoneyAmount;
  methods: AcquisitionMethod[];
}

/** 利用登録の方針 */
export interface MembershipPolicy {
  policy_id: string;
  fees: MembershipFee[];
  accepted_documents: DocumentKind[];
  valid_years: number;
}

/** 保存の方針 */
export interface RetentionPolicy {
  policy_id: string;
  rules: RetentionRule[];
}

/** お知らせの方針 */
export interface NotificationPolicy {
  policy_id: string;
  templates: NoticeTemplate[];
  quiet_hours: TimeWindow;
  postage: MoneyAmount;
}

/** 開館の方針 */
export interface OpeningPolicy {
  policy_id: string;
  hours: OpeningHours[];
  holidays: Holiday[];
}

/** 目録の方針 */
export interface CatalogPolicy {
  policy_id: string;
  scheme: ClassificationScheme;
  import_formats: ImportFormat[];
  languages: LanguageCode[];
}

/** 監査の方針 — 監査の記録を残す操作と、記録を見てよい範囲。承認の操作は省けない。 */
export interface AuditPolicy {
  policy_id: string;
  actions: AuditAction[];
  access: AccessLevel;
  retention: RetentionRule;
}

/** 行事の方針 */
export interface EventPolicy {
  policy_id: string;
  default_fee: MoneyAmount;
  speaker_budget: BudgetLine;
  rooms: RoomKind[];
}

/** 電子資料の方針 */
export interface DigitalPolicy {
  policy_id: string;
  default_terms: LicenseTerms;
  loan_days: number;
}

/** 受け取り方 — 取り置きの受け取り方。mode が決める欄だけを持ち、ほかの mode の欄は書かない。 — mode で判別 */
export type PickupChoice =
  | {
      mode: "branch";
      branch?: BranchRef;
    }
  | {
      mode: "locker";
      locker_number?: string;
    }
  | {
      mode: "home_delivery";
      delivery_address?: PostalAddress;
      delivery_fee?: MoneyAmount;
    };

/** 払い方の選択 — method で判別 */
export type PaymentChoice =
  | {
      method: "cash";
    }
  | {
      method: "card";
      card_last_digits?: string;
    }
  | {
      method: "transfer";
      transfer_reference?: string;
    }
  | {
      method: "waiver";
      waiver_id?: string;
    };

/** 連絡の方法 — channel で判別 */
export type ContactChoice =
  | {
      channel: "email";
      email?: string;
    }
  | {
      channel: "sms";
      phone?: string;
    }
  | {
      channel: "post";
      postal?: PostalAddress;
    }
  | {
      channel: "app";
    };

/** 索引の一行 — 索引の一行。catalog_kind が指す相手を決める。件名・著者・シリーズのどれでも、相手の記録をキーで指す。 */
export interface CatalogEntry {
  entry_id: string;
  catalog_kind: CatalogKind;
  entry_key: string;
  sort_key: string;
  /** SubjectHeading を byKey で指す値（catalog_kind = subject のとき） — Contributor を byKey で指す値（catalog_kind = author のとき） — SeriesInfo を byKey で指す値（catalog_kind = series のとき） */
  target_key: string;
}

/** 状態の移り変わり — 記録の状態がどう移ったかと、移した記録。移した記録は種類をまたぐので、種類の欄で相手を選ぶ。 */
export interface StatusChange {
  change_id: string;
