  /** 記録そのものの控え。中身の欄とは別に、作った・変えた職員と時刻を持つ */
  record_meta: InventoryCountRecordMeta;
}

/** DigitalLicenseGrant.record_meta の入れ子スキーマ */
export interface DigitalLicenseGrantRecordMeta {
  created_at: string;
  created_by: string;
  updated_at: string;
  updated_by: string | null;
  /** 変えるたびに 1 ずつ上げる */
  revision: number;
  source_terminal?: string;
  note?: string;
}

/** 電子資料の契約 — 電子資料の利用の契約。席ごとに今使っている利用者を持ち、契約の期間が過ぎたら席を空ける。 — lteRef(field=seats, target=DigitalLicenseGrant.terms.seats) — 参照先の値以下であること — drm_key は意図的に持たない: 利用の制御は配信の委託先が持つ */
export interface DigitalLicenseGrant {
  /** 記録の種類の判別子。どの記録も同じ名前の欄に固定の値を持つので、受け取った側はこの欄だけで形を選べる — 常に "lib.digital-license-grant" */
  record_type: "lib.digital-license-grant";
  /** 常に 1 */
  schema_version: 1;
  grant_id: string;
  /** CatalogRecord を byKey で指す値 */
  catalog_key: string;
  terms: LicenseTerms;
  seats: LicenseSeat[];
  vendor: VendorTerms;
  /** 記録そのものの控え。中身の欄とは別に、作った・変えた職員と時刻を持つ */
  record_meta: DigitalLicenseGrantRecordMeta;
}

/** SurveyResponse.record_meta の入れ子スキーマ */
export interface SurveyResponseRecordMeta {
  created_at: string;
  created_by: string;
  updated_at: string;
  updated_by: string | null;
  /** 変えるたびに 1 ずつ上げる */
  revision: number;
  source_terminal?: string;
  note?: string;
}

/** アンケート — 利用者アンケートの回答。名前は聞かず、利用者の区分と館だけを持つ。 — uniqueBy(field=sections, keys=["section_id"]) — 配列内で重複しないこと。field 省略時は要素そのもの — member_id は意図的に持たない: 誰の回答かは持たない */
export interface SurveyResponse {
  /** 記録の種類の判別子。どの記録も同じ名前の欄に固定の値を持つので、受け取った側はこの欄だけで形を選べる — 常に "lib.survey-response" */
  record_type: "lib.survey-response";
  /** 常に 1 */
  schema_version: 1;
  response_id: string;
  branch: BranchRef;
  category: MemberCategory;
  sections: SurveySection[];
  answered_at: string;
  /** 記録そのものの控え。中身の欄とは別に、作った・変えた職員と時刻を持つ */
  record_meta: SurveyResponseRecordMeta;
}

/** AuditEntry.record_meta の入れ子スキーマ */
export interface AuditEntryRecordMeta {
  created_at: string;
  created_by: string;
  updated_at: string;
  updated_by: string | null;
  /** 変えるたびに 1 ずつ上げる */
  revision: number;
  source_terminal?: string;
  note?: string;
}

/** 監査の記録 — 記録への操作を一件ずつ残す監査の記録。前の記録のハッシュを持って連なり、途中を消すと連なりが切れて分かる。指す記録は種類をまたぐので、種類の欄で相手を選ぶ。 — chainedBy(field=previous_entry_hash) — 直前の世代を、世代番号ではなくその digest で固定すること — monotonicPerKey(keys=["sequence"]) — keys の組ごとに単調増加すること — ip_address は意図的に持たない: 端末の番号で足りる */
export interface AuditEntry {
  /** 記録の種類の判別子。どの記録も同じ名前の欄に固定の値を持つので、受け取った側はこの欄だけで形を選べる — 常に "lib.audit-entry" */
  record_type: "lib.audit-entry";
  /** 常に 1 */
  schema_version: 1;
  entry_id: string;
  sequence: number;
  /** pattern(regex=^sha256:[A-Za-z0-9_-]+$) — 正規表現に一致すること */
  previous_entry_hash: string | null;
  occurred_at: string;
  action: AuditAction;
  actor: AuditActor;
  target: AuditTarget;
  /** record_type が名指しする artifact を byKey で指す値 */
  records: RecordRef[];
  changes: AuditChange[];
  detail?: unknown;
  /** 記録そのものの控え。中身の欄とは別に、作った・変えた職員と時刻を持つ */
  record_meta: AuditEntryRecordMeta;
}

/** CatalogIndex.record_meta の入れ子スキーマ */
export interface CatalogIndexRecordMeta {
  created_at: string;
  created_by: string;
  updated_at: string;
  updated_by: string | null;
  /** 変えるたびに 1 ずつ上げる */
  revision: number;
  source_terminal?: string;
  note?: string;
}

/** 索引 — 件名・著者・シリーズの索引。行ごとに索引の種類を持ち、種類に応じて指す相手が変わる。 — sortedBy(field=entries, keys=["catalog_kind"]) — 配列がこの順で並んでいること。field 省略時は要素そのもので比較 — full_text は意図的に持たない: 本文の索引は持たない */
export interface CatalogIndex {
  /** 記録の種類の判別子。どの記録も同じ名前の欄に固定の値を持つので、受け取った側はこの欄だけで形を選べる — 常に "lib.catalog-index" */
  record_type: "lib.catalog-index";
  /** 常に 1 */
  schema_version: 1;
  index_id: string;
  /** sortedBy(field=sort_key) — 配列がこの順で並んでいること。field 省略時は要素そのもので比較 */
  entries: CatalogEntry[];
  stats: IndexStats;
  built_at: string;
  /** 記録そのものの控え。中身の欄とは別に、作った・変えた職員と時刻を持つ */
  record_meta: CatalogIndexRecordMeta;
}

