// SpecBoard がプロジェクト「Harbor City Library Network」から作ったファイルです。書き換えはプロジェクトで
import { z } from "zod";

// オブジェクトは z.strictObject です。未知のフィールドは strip されず拒否されます
// （JSON Schema 出力の additionalProperties: false と一致させています）。

// 「未生成の rule」は、他文書を参照するか式を含むため、この生成器では検証コードに
// できないものです。コメントとしてのみ残しています。機械可読な定義が必要な場合は
// JSON Schema 出力の x-rules を参照してください。

/** 通貨 — 金額の単位。館の会計は円で締めるが、海外の出版社への発注と寄贈の評価額は外貨で受ける。換算は会計の側で行い、ここでは持たない。 */
export const CurrencyCode = z.enum(["JPY", "USD", "EUR"]);
export type CurrencyCode = z.infer<typeof CurrencyCode>;

/** 端数の扱い — 延滞金と按分した送料に 1 円未満が出たときの扱い。 */
export const RoundingMode = z.enum(["floor", "round", "ceil"]);
export type RoundingMode = z.infer<typeof RoundingMode>;

/** 資料の種類 — 貸出の規則と棚の割り当てを分ける単位。電子書籍は棚を持たないが、貸出の規則は同じ表で引く。 */
export const MaterialType = z.enum(["book", "magazine", "audio", "video", "map", "kit", "ebook", "score", "newspaper", "game"]);
export type MaterialType = z.infer<typeof MaterialType>;

/** 利用者の区分 — 貸出の上限と延滞金の率を変える区分。年齢で自動では変えず、更新の窓口で確かめて変える。 */
export const MemberCategory = z.enum(["adult", "child", "student", "senior", "corporate"]);
export type MemberCategory = z.infer<typeof MemberCategory>;

/** 利用者の状態 */
export const MemberStatus = z.enum(["active", "suspended", "expired"]);
export type MemberStatus = z.infer<typeof MemberStatus>;

/** 貸出の状態 — 返却の記録が付いた時点で returned。紛失の届けが出たものは lost にして延滞金を止める。 */
export const LoanStatus = z.enum(["open", "returned", "overdue", "lost"]);
export type LoanStatus = z.infer<typeof LoanStatus>;

/** 予約の状態 */
export const ReservationStatus = z.enum(["waiting", "ready", "collected", "cancelled", "expired"]);
export type ReservationStatus = z.infer<typeof ReservationStatus>;

/** 配送の状態 — 館間配送の荷の状態。荷を開けて数が合わないときは rejected にして送り元へ戻す。 */
export const TransferStatus = z.enum(["requested", "packed", "in_transit", "received", "rejected"]);
export type TransferStatus = z.infer<typeof TransferStatus>;

/** 資料の傷み */
export const CopyCondition = z.enum(["new", "good", "worn", "damaged"]);
export type CopyCondition = z.infer<typeof CopyCondition>;

/** 棚の区域 — 開架・参考・児童・閉架。閉架の資料は予約を通してだけ出す。 */
export const ShelfZone = z.enum(["general", "reference", "children", "closed_stack"]);
export type ShelfZone = z.infer<typeof ShelfZone>;

/** 曜日 */
export const Weekday = z.enum(["mon", "tue", "wed", "thu", "fri", "sat", "sun"]);
export type Weekday = z.infer<typeof Weekday>;

/** 知らせる手段 — 利用者が選んだ手段で知らせる。郵便は費用がかかるので、延滞の三度目の知らせだけに使う。 */
export const NotificationChannel = z.enum(["email", "sms", "post", "app"]);
export type NotificationChannel = z.infer<typeof NotificationChannel>;

/** 延滞金の理由 */
export const FineReason = z.enum(["overdue", "damage", "loss"]);
export type FineReason = z.infer<typeof FineReason>;

/** 払い方 */
export const PaymentMethod = z.enum(["cash", "card", "transfer", "waiver"]);
export type PaymentMethod = z.infer<typeof PaymentMethod>;

/** 受け入れの方法 */
export const AcquisitionMethod = z.enum(["purchase", "donation", "exchange"]);
export type AcquisitionMethod = z.infer<typeof AcquisitionMethod>;

/** 発注の状態 — 一部だけ届いた発注は partially_received のまま、残りが届くか取り消すまで閉じない。 */
export const OrderStatus = z.enum(["draft", "ordered", "partially_received", "received", "cancelled"]);
export type OrderStatus = z.infer<typeof OrderStatus>;

/** 取引先の種類 */
export const VendorKind = z.enum(["publisher", "distributor", "bookstore"]);
export type VendorKind = z.infer<typeof VendorKind>;

/** 行事の種類 */
export const EventKind = z.enum(["reading", "workshop", "exhibition", "lecture"]);
export type EventKind = z.infer<typeof EventKind>;

/** 対象の年齢 */
export const AudienceAge = z.enum(["children", "teens", "adults", "all"]);
export type AudienceAge = z.infer<typeof AudienceAge>;

/** 部屋の種類 */
export const RoomKind = z.enum(["study", "meeting", "hall"]);
export type RoomKind = z.infer<typeof RoomKind>;

/** 予約の確定 */
export const BookingStatus = z.enum(["held", "confirmed", "cancelled"]);
export type BookingStatus = z.infer<typeof BookingStatus>;

/** 職員の役割 — 記録に名前を残す職員の役割。ボランティアは承認の欄に名前を書けない。 */
export const StaffRole = z.enum(["librarian", "clerk", "manager", "volunteer"]);
export type StaffRole = z.infer<typeof StaffRole>;

/** 勤務の区分 */
export const ShiftKind = z.enum(["morning", "afternoon", "evening"]);
export type ShiftKind = z.infer<typeof ShiftKind>;

/** 監査の操作 */
export const AuditAction = z.enum(["create", "update", "delete", "approve", "reject"]);
export type AuditAction = z.infer<typeof AuditAction>;

/** 記録の種類 — 監査と索引が指す記録の種類。record_type の値から接頭辞を外したもの。 */
export const RecordKind = z.enum(["loan-record", "reservation", "transfer-manifest", "purchase-order", "fine-assessment"]);
export type RecordKind = z.infer<typeof RecordKind>;

/** 言語 */
export const LanguageCode = z.enum(["ja", "en", "zh", "ko", "es"]);
export type LanguageCode = z.infer<typeof LanguageCode>;

/** 分類法 */
export const ClassificationScheme = z.enum(["ndc", "ddc", "local"]);
export type ClassificationScheme = z.infer<typeof ClassificationScheme>;

/** 形態 */
export const ItemFormat = z.enum(["print", "large_print", "braille", "digital"]);
export type ItemFormat = z.infer<typeof ItemFormat>;

/** 配送の手段 */
export const DeliveryMode = z.enum(["van", "courier", "post"]);
export type DeliveryMode = z.infer<typeof DeliveryMode>;

/** 巡回車の経路 — 巡回車は週に二回、四つの経路で分館を回る。経路の外の館へは宅配で送る。 */
export const VanRoute = z.enum(["north", "south", "east", "west"]);
export type VanRoute = z.infer<typeof VanRoute>;

/** 受け取りの場所 */
export const HoldPickup = z.enum(["branch", "locker", "home_delivery"]);
export type HoldPickup = z.infer<typeof HoldPickup>;

/** 延長の可否 */
export const RenewalRule = z.enum(["allowed", "once", "never"]);
export type RenewalRule = z.infer<typeof RenewalRule>;

/** シリーズの状態 */
export const SeriesStatus = z.enum(["ongoing", "completed", "discontinued"]);
export type SeriesStatus = z.infer<typeof SeriesStatus>;

/** 電子資料の契約 */
export const DigitalLicense = z.enum(["one_user", "multi_user", "unlimited"]);
export type DigitalLicense = z.infer<typeof DigitalLicense>;

/** 公開の範囲 */
export const AccessLevel = z.enum(["public", "staff", "restricted"]);
export type AccessLevel = z.infer<typeof AccessLevel>;

/** 承認の結果 */
export const ApprovalDecision = z.enum(["approved", "rejected", "deferred"]);
export type ApprovalDecision = z.infer<typeof ApprovalDecision>;

/** 満足度 — 利用者アンケートの五段階。3 を「ふつう」とする。 */
export const SurveyScale = z.enum(["1", "2", "3", "4", "5"]);
export type SurveyScale = z.infer<typeof SurveyScale>;

/** 除籍の理由 */
export const WeedingReason = z.enum(["outdated", "damaged", "duplicate", "low_use"]);
export type WeedingReason = z.infer<typeof WeedingReason>;

/** 予算の期間 */
export const BudgetPeriod = z.enum(["monthly", "quarterly", "yearly"]);
export type BudgetPeriod = z.infer<typeof BudgetPeriod>;

/** 連絡先の用途 */
export const ContactPurpose = z.enum(["billing", "notices", "emergency"]);
export type ContactPurpose = z.infer<typeof ContactPurpose>;

/** 本人確認の書類 */
export const DocumentKind = z.enum(["id_card", "passport", "student_card", "health_card"]);
export type DocumentKind = z.infer<typeof DocumentKind>;

/** 索引の種類 — 索引の一行が何の索引かを言う。種類ごとに指す相手が違う。 */
export const CatalogKind = z.enum(["subject", "author", "series"]);
export type CatalogKind = z.infer<typeof CatalogKind>;

/** 保管の温度帯 */
export const TemperatureZone = z.enum(["normal", "cool", "archive"]);
export type TemperatureZone = z.infer<typeof TemperatureZone>;

/** 取り込みの形式 */
export const ImportFormat = z.enum(["marc21", "csv", "json"]);
export type ImportFormat = z.infer<typeof ImportFormat>;

/** 優先度 */
export const PriorityLevel = z.enum(["low", "normal", "high", "urgent"]);
export type PriorityLevel = z.infer<typeof PriorityLevel>;

/** 金額 — 金額は通貨と最小単位の整数で持つ。浮動小数で持つと延滞金の合計が館ごとにずれるので、ここへ切り出して全部の金額欄が同じ形を使う。 */
export const MoneyAmount = z.strictObject({
  currency: CurrencyCode,
  // 通貨の最小単位での整数。円なら 1 円単位
  minor_units: z.int(),
  rounding: RoundingMode.optional(),
});
export type MoneyAmount = z.infer<typeof MoneyAmount>;

/** 住所 — 郵送と配送に使う住所。行は利用者が書いたとおりに持ち、正規化は送り状を作るときにだけ行う。 */
export const PostalAddress = z.strictObject({
  // ハイフンを含めない 7 桁
  postal_code: z.string().regex(/^[0-9]{7}$/),
  region: z.string(),
  city: z.string(),
  lines: z.array(z.string()),
  address_id: z.uuid().optional(),
});
export type PostalAddress = z.infer<typeof PostalAddress>;

/** 連絡先 */
export const ContactPoint = z.strictObject({
  contact_id: z.uuid(),
  purpose: ContactPurpose,
  channel: NotificationChannel,
  // メールアドレス・電話番号・住所のいずれか。channel が決める
  address: z.string(),
});
export type ContactPoint = z.infer<typeof ContactPoint>;

/** 人の名前 — 姓と名を分けて持つ。読みは窓口で確かめたものだけを入れる。 */
export const PersonName = z.strictObject({
  family: z.string(),
  given: z.string(),
  family_kana: z.string().optional(),
  given_kana: z.string().optional(),
});
export type PersonName = z.infer<typeof PersonName>;

/** 期間 — 両端を含む期間。終わりの無い期間は until を null にする。 */
export const DateRange = z.strictObject({
  since: z.iso.datetime(),
  until: z.iso.datetime().nullable(),
});
export type DateRange = z.infer<typeof DateRange>;

/** 時間帯 */
export const TimeWindow = z.strictObject({
  // HH:MM
  opens: z.string(),
  // HH:MM
  closes: z.string(),
});
export type TimeWindow = z.infer<typeof TimeWindow>;

/** 職員 — 記録に残す職員。名前は控えず、職員の id と役割だけを持つ。 */
export const StaffRef = z.strictObject({
  staff_id: z.uuid(),
  role: StaffRole,
});
export type StaffRef = z.infer<typeof StaffRef>;

/** 館 */
export const BranchRef = z.strictObject({
  branch_id: z.uuid(),
  // 館の 3 文字の略号
  code: z.string(),
});
export type BranchRef = z.infer<typeof BranchRef>;

/** 記録への参照 — どの種類の記録かと、その記録の番号の組。番号だけでは種類をまたいで重なるので、必ず二つで指す。 */
export const RecordRef = z.strictObject({
  // 指す記録の record_type
  record_type: z.string(),
  // 指す記録の番号
  record_key: z.string(),
});
export type RecordRef = z.infer<typeof RecordRef>;

/** 承認の印 — 承認した職員と結果と時刻。承認の欄を持つ記録はどれもこの形を使う。 */
export const ApprovalStamp = z.strictObject({
  decision: ApprovalDecision,
  approver: StaffRef,
  decided_at: z.iso.datetime(),
  comment: z.string().optional(),
});
export type ApprovalStamp = z.infer<typeof ApprovalStamp>;

/** 識別子 */
export const Identifier = z.strictObject({
  // isbn・issn・館の登録番号など
  scheme: z.string(),
  identifier_value: z.string(),
});
export type Identifier = z.infer<typeof Identifier>;

/** 棚の位置 */
export const ShelfLocation = z.strictObject({
  location_id: z.uuid(),
  zone: ShelfZone,
  shelf: z.string(),
  position: z.int(),
});
export type ShelfLocation = z.infer<typeof ShelfLocation>;

/** 請求記号 — 分類記号と著者記号の組。分類法が館の独自分類のときは cutter を持たない。 */
export const CallNumber = z.strictObject({
  scheme: ClassificationScheme,
  class_number: z.string(),
  cutter: z.string().optional(),
});
export type CallNumber = z.infer<typeof CallNumber>;

/** 著者など */
export const Contributor = z.strictObject({
  contributor_id: z.uuid(),
  name: PersonName,
  // 著・編・訳・絵など
  role: z.string(),
});
export type Contributor = z.infer<typeof Contributor>;

/** シリーズ */
export const SeriesInfo = z.strictObject({
  series_id: z.uuid(),
  title: z.string(),
  number: z.string().optional(),
  status: SeriesStatus,
});
export type SeriesInfo = z.infer<typeof SeriesInfo>;

/** 形態の記述 */
export const PhysicalDescription = z.strictObject({
  format: ItemFormat,
  pages: z.int().optional(),
  height_cm: z.int().optional(),
});
export type PhysicalDescription = z.infer<typeof PhysicalDescription>;

/** 件名 */
export const SubjectHeading = z.strictObject({
  heading_id: z.uuid(),
  heading: z.string(),
  scheme: z.string(),
});
export type SubjectHeading = z.infer<typeof SubjectHeading>;

/** 資料の状態 — 点検と返却のたびに付ける状態。前の状態は消さずに、記録の側に並べて残す。 */
export const ItemCondition = z.strictObject({
  condition: CopyCondition,
  noted_at: z.iso.datetime(),
  noted_by: StaffRef,
});
export type ItemCondition = z.infer<typeof ItemCondition>;

/** 貸出の一点 */
export const LoanLine = z.strictObject({
  item_id: z.uuid(),
  due_on: z.iso.datetime(),
  fee: MoneyAmount.optional(),
});
export type LoanLine = z.infer<typeof LoanLine>;

/** 返却の一点 */
export const ReturnLine = z.strictObject({
  item_id: z.uuid(),
  returned_at: z.iso.datetime(),
  condition: ItemCondition,
  late_fee: MoneyAmount.nullable(),
});
export type ReturnLine = z.infer<typeof ReturnLine>;

/** 荷の一点 */
export const PackedItem = z.strictObject({
  item_id: z.uuid(),
  from_branch: BranchRef,
  to_branch: BranchRef,
  declared_value: MoneyAmount,
});
export type PackedItem = z.infer<typeof PackedItem>;

/** 荷の封 — 封の番号と封をした職員。受け取った館は封の番号を確かめてから開ける。 */
export const PackageSeal = z.strictObject({
  seal_id: z.string(),
  sealed_by: StaffRef,
  sealed_at: z.iso.datetime(),
});
export type PackageSeal = z.infer<typeof PackageSeal>;

/** 発注の一行 — 未生成の rule: derivedFrom(field=total, from=unit_price, note=単価と数から計算し直して、合わない行を受け付けない) — from から再計算した値と一致すること */
export const OrderLine = z.strictObject({
  line_id: z.uuid(),
  title: z.string(),
  isbn: z.string().optional(),
  quantity: z.int(),
  unit_price: MoneyAmount,
  total: MoneyAmount,
});
export type OrderLine = z.infer<typeof OrderLine>;

/** 税 */
export const TaxLine = z.strictObject({
  tax_id: z.uuid(),
  rate_percent: z.int(),
  amount: MoneyAmount,
});
export type TaxLine = z.infer<typeof TaxLine>;

/** 請求の一行 */
export const InvoiceLine = z.strictObject({
  order_line_id: z.uuid(),
  amount: MoneyAmount,
  tax: TaxLine,
});
export type InvoiceLine = z.infer<typeof InvoiceLine>;

/** 支払いの一行 */
