/** 全体の設定 — 図書館ネットワーク全体の設定。中央館が版を重ねて発行し、各館は受け取った版で貸出・予約・延滞金・配送を判断する。前の版を番号で指して連なり、同じ版の番号で中身の違うものを受け付けない。方針ごとの欄はそれぞれの値の形に切り出し、この記録は方針を並べる入れ物にとどめる。館ごとの差は館の扱える範囲（貸出の方針の中）で表し、館ごとの設定の記録は作らない。 — 未生成の rule: monotonicPerKey(keys=["network_id"], note=受け取った版より古い版で置き換えない) — keys の組ごとに単調増加すること — 未生成の rule: chainedBy(field=previous_configuration_key, note=版の番号の大小だけで比べず、前の版を指しているかを見る) — 直前の世代を、世代番号ではなくその digest で固定すること — branch_overrides は意図的に持たない: 館ごとの差は貸出の方針の館の扱える範囲で表す */
export const NetworkConfiguration = z.strictObject({
  // 記録の種類の判別子。どの記録も同じ名前の欄に固定の値を持つので、受け取った側はこの欄だけで形を選べる
  // 常に "lib.network-configuration"
  record_type: z.literal("lib.network-configuration"),
  // 常に 1
  schema_version: z.literal(1),
  network_id: z.uuid(),
  version: z.int(),
  // 直前の版の番号。最初の版では null
  // NetworkConfiguration を byKey で指す値
  previous_configuration_key: z.string().nullable(),
  issued_at: z.iso.datetime(),
  // 中央館の事務の設定
  head_office: z.strictObject({
    // 目録の作り方。版が変わる途中は二つの方式が並ぶ
    cataloging: z.strictObject({
      active_scheme: z.strictObject({
        scheme_id: z.uuid(),
        // 方式の版。上がったら各館は目録を作り直す
        scheme_version: z.int(),
        // 一件の目録を外に頼むときの料金
