  // 記録そのものの控え。中身の欄とは別に、作った・変えた職員と時刻を持つ
  record_meta: z.strictObject({
    created_at: z.iso.datetime(),
    created_by: z.uuid(),
    updated_at: z.iso.datetime(),
    updated_by: z.uuid().nullable(),
    // 変えるたびに 1 ずつ上げる
    revision: z.int(),
    source_terminal: z.string().optional(),
    note: z.string().optional(),
  }),
});
export type AuditEntry = z.infer<typeof AuditEntry>;

/** 索引 — 件名・著者・シリーズの索引。行ごとに索引の種類を持ち、種類に応じて指す相手が変わる。 — sortedBy(field=entries, keys=["catalog_kind"]) — 配列がこの順で並んでいること。field 省略時は要素そのもので比較 — full_text は意図的に持たない: 本文の索引は持たない */
export const CatalogIndex = z.strictObject({
  // 記録の種類の判別子。どの記録も同じ名前の欄に固定の値を持つので、受け取った側はこの欄だけで形を選べる
  // 常に "lib.catalog-index"
  record_type: z.literal("lib.catalog-index"),
  // 常に 1
  schema_version: z.literal(1),
  index_id: z.uuid(),
  entries: z.array(CatalogEntry).refine(a => a.every((v, i, arr) => i === 0 || String(arr[i - 1].sort_key).localeCompare(String(v.sort_key)) <= 0), { message: "entries は昇順である必要があります" }),
  stats: IndexStats,
  built_at: z.iso.datetime(),
  // 記録そのものの控え。中身の欄とは別に、作った・変えた職員と時刻を持つ
  record_meta: z.strictObject({
    created_at: z.iso.datetime(),
    created_by: z.uuid(),
    updated_at: z.iso.datetime(),
    updated_by: z.uuid().nullable(),
    // 変えるたびに 1 ずつ上げる
    revision: z.int(),
    source_terminal: z.string().optional(),
    note: z.string().optional(),
  }),
});
export type CatalogIndex = z.infer<typeof CatalogIndex>;
